/* From Uiverse.io by Rkyz - Tags: animation, loader, animal */
.__UIV_SCOPE__ .loader {
  height: 50px;
  width: 20rem;
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 15px;
}

.__UIV_SCOPE__ .dot-two {
  background-color: black;
  height: 30px;
  width: 30px;
  border-radius: 50%;
  padding: 4px;
  color: white;
}

.__UIV_SCOPE__ .dot-one,
.__UIV_SCOPE__ .dot-three {
  background-color: black;
  height: 30px;
  width: 20px;
  border-radius: 50%;
  text-align: center;
  animation: flap-wings 1s infinite ease-in-out;
}

.__UIV_SCOPE__ .dot-two {
  position: relative;
  height: 30px;
  width: 30px;
  border-radius: 50%;
  background-color: black;
  animation: flap-wings 1s infinite ease-in-out;
  animation-delay: 0.1s;
}

.__UIV_SCOPE__ .dot-two::before,
.__UIV_SCOPE__ .dot-two::after {
  content: "";
  position: absolute;
  background-color: black;
}

.__UIV_SCOPE__ .dot-two::before {
  height: 20px;
  width: 10px;
  bottom: 20px;
  left: 1px;
  border-radius: 50% 50% 0 0;
  transform: rotate(-20deg);
}

.__UIV_SCOPE__ .dot-two::after {
  height: 20px;
  width: 10px;
  bottom: 20px;
  left: 19px;
  transform: rotate(20deg);
  border-radius: 50% 50% 0 0;
}

.__UIV_SCOPE__ .dot-one::before,
.__UIV_SCOPE__ .dot-one::after,
.__UIV_SCOPE__ .dot-three::before,
.__UIV_SCOPE__ .dot-three::after {
  content: "";
  position: absolute;
  background-color: white;
}

.__UIV_SCOPE__ .dot-one::before,
.__UIV_SCOPE__ .dot-three::before {
  height: 30px;
  width: 20px;
  top: 10px;
  left: 0;
  background-color: #e8e8e8;
 /*chnage this if u need dark mode to #212121 if need light mode #e8e8e8*/
  border-radius: 50% 50% 0 0;
}

@keyframes flap-wings {
  0%,
  100% {
    transform: translateY(0);
  }

  50% {
    transform: translateY(-20px);
  }
}
